insert into public.cmc_task_plan_template_versions (template_id,version,snapshot,created_at) values ('0b487ffb-2272-5b66-9725-290c4c62e9b8',2,'{"template":{"title":"Church Planting Launch Roadmap","slug":"church-planting-launch-roadmap","description":"A customizable CMC roadmap that helps a pioneer and regional leader move from an affirmed call through launch, stabilization, and a growing culture of multiplication.","stage_key":"deploy"},"sections":[{"id":"ffbd8d03-4651-5894-8143-052a79bf90dd","title":"Phase 1 · Discern and Align","description":"Confirm calling, readiness, relationships, and alignment before building a launch plan.","position":0,"tasks":[{"title":"Affirm the call","description":"Clarify the pioneer’s calling, capacity, and current readiness with trusted leaders.","task_type":"group","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":[],"id":"2407b611-aa2a-5988-b43e-454c471ea4d3","position":0,"relative_start_days":null,"relative_due_days":null,"resource_url":"","tasks":[{"title":"Write a personal calling statement","description":"Describe the people or place you feel called to serve, why church planting may be the right response, and what has brought clarity so far.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":1,"tags":["calling"],"relative_due_days":14,"id":"f45f8b8b-9b9b-50bc-abca-b93353385956","position":0,"relative_start_days":0,"resource_url":"","tasks":[]},{"title":"Discuss the calling with your spouse or household","description":"If applicable, talk honestly about expectations, risks, family health, finances, and the support needed for the journey.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["family"],"relative_due_days":21,"id":"6377e1b6-7193-5c44-ab03-4e74016ea3f5","position":1,"relative_start_days":0,"resource_url":"","tasks":[]},{"title":"Invite feedback from trusted ministry leaders","description":"Ask two or three mature leaders to speak candidly about your character, gifting, leadership, and readiness.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["calling","feedback"],"relative_due_days":28,"id":"3f1f620a-db76-5ebf-89be-cc850db3377a","position":2,"relative_start_days":7,"resource_url":"","tasks":[]},{"title":"Complete assigned CMC discernment work","description":"Finish the assessments, application, and references assigned by your regional leader.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":2,"tags":["assessment"],"relative_due_days":42,"id":"d6a61d94-5e49-5eef-b12f-375f6c5f4aa5","position":3,"relative_start_days":21,"resource_url":"","tasks":[]},{"title":"Review discernment findings with your regional leader","description":"Identify strengths, growth areas, risks, and the next development steps together.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":false,"default_priority":1,"tags":["assessment","review"],"relative_due_days":49,"id":"ff6683f3-883e-5081-a0fe-ce1a8e2954a5","position":4,"relative_start_days":28,"resource_url":"","tasks":[]}]},{"title":"Establish support and coaching","description":"Build the relationships that will provide accountability, care, and practical guidance.","task_type":"group","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":[],"id":"91d86435-4624-5e90-8d93-5a78f8910048","position":1,"relative_start_days":null,"relative_due_days":null,"resource_url":"","tasks":[{"title":"Identify your primary CMC regional leader","description":"Confirm who will provide regional oversight and who should be contacted when decisions or concerns arise.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":false,"default_priority":3,"tags":["oversight"],"relative_due_days":14,"id":"914bc071-3a69-5bcd-961c-3b45e225b8e9","position":0,"relative_start_days":0,"resource_url":"","tasks":[]},{"title":"Select an approved church planting coach","description":"Work with your regional leader to choose a coach with relevant ministry and multiplication experience.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":true,"default_priority":3,"tags":["coaching"],"relative_due_days":35,"id":"0dfe3172-e1ba-5ae2-8756-94f8b288476d","position":1,"relative_start_days":14,"resource_url":"","tasks":[]},{"title":"Agree on the coaching relationship","description":"Set expectations for confidentiality, frequency, preparation, accountability, and duration.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["coaching"],"relative_due_days":42,"id":"01890373-e5e6-527e-845d-376a56059919","position":2,"relative_start_days":21,"resource_url":"","tasks":[]},{"title":"Schedule recurring coaching meetings","description":"Place a dependable meeting rhythm on both calendars and decide how progress will be reviewed.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["coaching"],"relative_due_days":49,"id":"08e315c4-e8f3-524c-a5fa-3bfb87c41f50","position":3,"relative_start_days":28,"resource_url":"","tasks":[]},{"title":"Create a personal and family care plan","description":"Name healthy rhythms, trusted support, boundaries, and warning signs that require attention.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["health","family"],"relative_due_days":56,"id":"09efe377-ce6d-5ca6-bf15-adc747f67935","position":4,"relative_start_days":35,"resource_url":"","tasks":[]}]},{"title":"Listen to the community","description":"Learn the people, stories, needs, assets, and spiritual landscape of the proposed mission field.","task_type":"group","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":[],"id":"20c93771-cba2-5976-b2fe-120bc1c4e31f","position":2,"relative_start_days":null,"relative_due_days":null,"resource_url":"","tasks":[{"title":"Define the initial ministry area","description":"Name the city, neighborhood, network, or people group being explored. This can be refined later.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["community"],"relative_due_days":21,"id":"a8129f89-816c-5b56-85f5-afb3d517ddaf","position":0,"relative_start_days":0,"resource_url":"","tasks":[]},{"title":"Review demographic and community information","description":"Study population, growth, languages, ages, economics, mobility, and other factors relevant to ministry.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["community","research"],"relative_due_days":35,"id":"5561c120-a869-5f84-93af-5c8c9a72cba8","position":1,"relative_start_days":14,"resource_url":"","tasks":[]},{"title":"Interview local leaders and residents","description":"Listen to educators, nonprofit leaders, business owners, pastors, and residents before proposing solutions.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["community","listening"],"relative_due_days":49,"id":"baf63a32-10e4-50e1-920f-d45b46e648b7","position":2,"relative_start_days":28,"resource_url":"","tasks":[]},{"title":"Prayer-walk and observe the area","description":"Pray, notice gathering places and rhythms, and record questions, opportunities, and signs of God’s activity.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["prayer","community"],"relative_due_days":56,"id":"99950b26-d9d9-5937-bdbc-029ebe1ad1e4","position":3,"relative_start_days":35,"resource_url":"","tasks":[]},{"title":"Summarize the ministry opportunity","description":"Describe who you hope to serve, what you have learned, existing community assets, and the gaps a new church could faithfully address.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":true,"default_priority":3,"tags":["community","review"],"relative_due_days":63,"id":"a07f9a1c-fedf-5f62-ba65-660834c852ef","position":4,"relative_start_days":42,"resource_url":"","tasks":[]}]},{"title":"Confirm Open Bible alignment","description":"Clarify denominational relationship, oversight, and the expectations for moving forward.","task_type":"group","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":[],"id":"f67de6ae-4ad1-5af1-81ed-8d098f234c07","position":3,"relative_start_days":null,"relative_due_days":null,"resource_url":"","tasks":[{"title":"Review CMC and Open Bible multiplication commitments","description":"Discuss the biblical convictions, relationships, accountability, and multiplication practices expected of a CMC pioneer.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["open-bible","alignment"],"relative_due_days":28,"id":"fdeda957-ca83-5872-9c16-48e26899b71e","position":0,"relative_start_days":7,"resource_url":"","tasks":[]},{"title":"Clarify the Open Bible affiliation pathway","description":"With your regional leader, identify the applicable credentialing, affiliation, chartering, governance, and reporting steps.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":false,"default_priority":3,"tags":["open-bible","governance"],"relative_due_days":49,"id":"02c9ac0a-372a-5ef2-88aa-c63afb66cc5b","position":1,"relative_start_days":28,"resource_url":"","tasks":[]},{"title":"Name the initial oversight structure","description":"Document who provides spiritual, financial, legal, and ministry accountability before a local board is formed.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":true,"default_priority":3,"tags":["governance"],"relative_due_days":56,"id":"f83ab5a5-76dc-561c-a85b-73788133989f","position":2,"relative_start_days":35,"resource_url":"","tasks":[]},{"title":"Set a provisional launch window","description":"Choose a realistic season rather than a fixed public date until readiness has been reviewed.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["timeline"],"relative_due_days":63,"id":"e48b872b-43da-5884-9460-1ef494a16ab9","position":3,"relative_start_days":42,"resource_url":"","tasks":[]},{"title":"Phase 1 readiness review","description":"The pioneer, coach, and regional leader agree on whether to proceed, pause for development, or revise the plan.","task_type":"milestone","is_required":true,"requires_approval":true,"participant_editable":false,"default_priority":1,"tags":["approval","milestone"],"relative_due_days":70,"id":"7a60b80c-95ce-5fde-9313-a6512289aaa6","position":4,"relative_start_days":49,"resource_url":"","tasks":[]}]}]},{"id":"b00a962f-50fb-5e67-9822-7e989cf0c16a","title":"Phase 2 · Form the Foundation","description":"Shape the ministry, prayer, team, financial, and administrative foundations that support a healthy launch.","position":1,"tasks":[{"title":"Clarify mission and ministry model","description":"Translate the calling and community learning into a focused ministry direction.","task_type":"group","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":[],"id":"ff4713ac-2017-5b7a-b6f4-fffde7cdfcb4","position":0,"relative_start_days":null,"relative_due_days":null,"resource_url":"","tasks":[{"title":"Draft the church’s mission","description":"Write a clear statement of who the church is called to serve and what it exists to do.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["vision"],"relative_due_days":84,"id":"dcced824-6ff9-5d7d-b70c-2202815c6eb7","position":0,"relative_start_days":63,"resource_url":"","tasks":[]},{"title":"Define core values and ministry convictions","description":"Name the behaviors and biblical commitments that will guide leadership, discipleship, mission, and multiplication.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["vision","culture"],"relative_due_days":98,"id":"6c2f9135-d773-58fe-acd1-e0e5e7b96e8f","position":1,"relative_start_days":77,"resource_url":"","tasks":[]},{"title":"Outline a disciple-making pathway","description":"Describe how people will encounter Jesus, grow as disciples, serve, lead, and participate in mission.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["discipleship"],"relative_due_days":105,"id":"c2465ee6-2d1f-5610-bc24-cda923ff028d","position":2,"relative_start_days":84,"resource_url":"","tasks":[]},{"title":"Choose an initial church planting model","description":"Define the likely approach, such as neighborhood, network, house church, multisite, or public gathering, and explain why it fits the context.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["model"],"relative_due_days":112,"id":"224c35a1-1147-501a-baa6-b6f495adf2f0","position":3,"relative_start_days":91,"resource_url":"","tasks":[]},{"title":"Review the ministry foundation with your coach","description":"Test the mission, values, disciple-making pathway, and model for clarity and alignment.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":true,"default_priority":3,"tags":["vision","review"],"relative_due_days":119,"id":"5cbb3b50-80f4-5f47-a709-f3f071b119c0","position":4,"relative_start_days":98,"resource_url":"","tasks":[]}]},{"title":"Build prayer and core-team support","description":"Develop spiritual support and begin forming a healthy, aligned team.","task_type":"group","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":[],"id":"084d4891-b553-5781-9aa6-8b5a84e03201","position":1,"relative_start_days":null,"relative_due_days":null,"resource_url":"","tasks":[{"title":"Create an intercessory prayer plan","description":"Set a rhythm for prayer requests, updates, confidentiality, and celebration.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["prayer"],"relative_due_days":84,"id":"c0eb4f6d-f3c3-5ea3-a541-9c79eb2ff4a1","position":0,"relative_start_days":63,"resource_url":"","tasks":[]},{"title":"Recruit an initial prayer team","description":"Invite people who will pray consistently for the pioneer, family, team, and community.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["prayer","team"],"relative_due_days":105,"id":"84794ca9-7520-5cec-b166-f8c40948224c","position":1,"relative_start_days":84,"resource_url":"","tasks":[]},{"title":"Define the first core-team profile","description":"Describe the character, commitment, gifting, and cultural fit needed on the initial team.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["team"],"relative_due_days":112,"id":"673b2ef0-beea-51e0-b41c-550d93fc92f4","position":2,"relative_start_days":91,"resource_url":"","tasks":[]},{"title":"Invite and interview potential core-team members","description":"Share the vision, listen to their calling, and avoid promising roles before alignment is clear.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["team","recruiting"],"relative_due_days":140,"id":"9acc042e-9b53-5064-97a0-6410d77ff292","position":3,"relative_start_days":119,"resource_url":"","tasks":[]},{"title":"Adopt a core-team covenant","description":"Agree on spiritual health, conduct, communication, conflict, safeguarding, generosity, and participation.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":true,"default_priority":3,"tags":["team","culture"],"relative_due_days":154,"id":"3f9c37e4-20a1-5048-a632-20709b70803b","position":4,"relative_start_days":133,"resource_url":"","tasks":[]}]},{"title":"Build the financial plan","description":"Create transparent, accountable plans for launch funding and sustainable ministry.","task_type":"group","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":[],"id":"56d1f603-bc96-5f40-bb54-72ac04c2595a","position":2,"relative_start_days":null,"relative_due_days":null,"resource_url":"","tasks":[{"title":"Draft the launch budget","description":"Estimate one-time expenses, phased purchases, contingencies, and the funding needed before launch.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["finance"],"relative_due_days":98,"id":"a77f900d-2c42-5303-95e1-73c8a002f923","position":0,"relative_start_days":77,"resource_url":"","tasks":[]},{"title":"Draft a first-year operating budget","description":"Estimate conservative income and recurring ministry, staffing, facility, insurance, and administrative expenses.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["finance"],"relative_due_days":112,"id":"5b6f37bf-f59b-5575-a790-5b59835531e3","position":1,"relative_start_days":91,"resource_url":"","tasks":[]},{"title":"Confirm regional financial requirements","description":"Ask the regional leader which approvals, accounts, controls, reporting, and fundraising practices are required.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":false,"default_priority":3,"tags":["finance","open-bible"],"relative_due_days":119,"id":"dc40033e-7a14-5c1f-8402-bf5a893ed2f9","position":2,"relative_start_days":98,"resource_url":"","tasks":[]},{"title":"Create a funding strategy","description":"Identify potential sending churches, partners, personal support, grants, and earned or congregational income without assuming every source will materialize.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["finance","fundraising"],"relative_due_days":126,"id":"082c57f5-5c5a-503b-9a4b-343e4a8d0032","position":3,"relative_start_days":105,"resource_url":"","tasks":[]},{"title":"Set up donor communication and tracking","description":"Choose a simple, secure way to record commitments, gifts, restrictions, acknowledgments, and regular updates.","task_type":"task","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":["finance","fundraising"],"relative_due_days":147,"id":"5431065f-40d7-5699-bdf3-21ea277d59c2","position":4,"relative_start_days":126,"resource_url":"","tasks":[]},{"title":"Approve the launch and operating budgets","description":"The appropriate regional leader or oversight group reviews assumptions, controls, and financial viability.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":false,"default_priority":1,"tags":["finance","approval"],"relative_due_days":161,"id":"c9310447-392a-541f-a762-aa564f0633ab","position":5,"relative_start_days":140,"resource_url":"","tasks":[]}]},{"title":"Establish administration and risk safeguards","description":"Put proportionate legal, financial, safety, and data practices in place with qualified guidance.","task_type":"group","is_required":true,"requires_approval":false,"participant_editable":true,"default_priority":3,"tags":[],"id":"d20f7330-042e-5ec4-95f9-d89b6959dd63","position":3,"relative_start_days":null,"relative_due_days":null,"resource_url":"","tasks":[{"title":"Confirm the legal and organizational pathway","description":"Follow the direction of Open Bible regional leadership and qualified legal or tax professionals before creating entities or filing government forms.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":false,"default_priority":3,"tags":["legal","open-bible"],"relative_due_days":105,"id":"ff77e9b8-4b31-585b-8942-8a545de7f2de","position":0,"relative_start_days":84,"resource_url":"","tasks":[]},{"title":"Establish banking, bookkeeping, and financial controls","description":"Use approved accounts, separation of duties, expense documentation, and regular financial reporting.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":true,"default_priority":3,"tags":["finance","governance"],"relative_due_days":140,"id":"599ea168-6f14-5677-bd32-ef5257880522","position":1,"relative_start_days":119,"resource_url":"","tasks":[]},{"title":"Confirm insurance coverage","description":"Review general liability, property, workers’ compensation, pastoral, abuse and molestation, vehicle, cyber, and event coverage as applicable.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":true,"default_priority":3,"tags":["risk","insurance"],"relative_due_days":154,"id":"4f993bac-5be7-5f16-b2e5-d2fbfa7bdb6c","position":2,"relative_start_days":133,"resource_url":"","tasks":[]},{"title":"Adopt safeguarding and background-check practices","description":"Document how children, vulnerable people, volunteers, records, incidents, and mandated reporting will be handled.","task_type":"task","is_required":true,"requires_approval":true,"participant_editable":true,"default_priority":3,"tags":["safety","policy"],"relative_due_days":168,"id":"3b49c613-c1f8-5a0f-ba73-b7f4a5c63bf5","position":3,"re